update public.shows_app_research_calendar_controls r
set source_refs=coalesce(source_refs,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('url',detail_data->>'official_source_url','title',coalesce(nullif(detail_data->>'source_label',''),'Current official source'),'checked_at','2026-09-30','verification_scope','CURRENT_REVERIFIED')),updated_at=now()
where control_id in ('R2026-016-MIAMI-CARNIVAL','R2026-028-WELLINGTON-NNO','R2026-046-PALM-BAY-FALL-FEST','R2026-029-RPB-ROCK-N-FALL','R2026-036-PALM-BAY-SENIOR','R2026-037-WEST-BOYNTON-SENIOR','R2026-038-FLIBS','R2026-048-VERO-HALLOWEEN','R2026-047-COCOA-FALL')
and not exists (select 1 from jsonb_array_elements(coalesce(r.source_refs,'[]'::jsonb)) e where e->>'url'=r.detail_data->>'official_source_url' and e->>'checked_at'='2026-09-30');
update public.shows_app_research_calendar_controls set source_refs=coalesce(source_refs,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('url','https://miamicarnival.org/about-us/','title','Miami Carnival 2026 official venues and times','checked_at','2026-09-30','verification_scope','CURRENT_REVERIFIED')) where control_id='R2026-016-MIAMI-CARNIVAL';
update public.shows_app_research_calendar_controls set source_refs=coalesce(source_refs,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('url','https://www.eventbrite.com/e/october-25-2026-vendor-fair-tickets-1999937374524','title','Greater Palm Bay Senior Activity Center — Oct. 25, 2026 Vendor Fair organizer listing','checked_at','2026-09-30','verification_scope','CURRENT_REVERIFIED')) where control_id='R2026-036-PALM-BAY-SENIOR';
update public.shows_app_research_calendar_controls set source_refs=coalesce(source_refs,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('url','https://retirement-times.com/wp-content/uploads/2026/01/FACT_SHEETS-2026SENIOREXPOS.pdf','title','West Boynton 2026 Senior Expo fact sheet','checked_at','2026-09-30','verification_scope','CURRENT_REVERIFIED'),jsonb_build_object('url','https://retirement-times.com/wp-content/uploads/2026/01/SEContracts-2026-HealthFairs-FILLABLE.pdf','title','2026 Senior Expo vendor-space application','checked_at','2026-09-30','verification_scope','CURRENT_REVERIFIED')) where control_id='R2026-037-WEST-BOYNTON-SENIOR';
do $$
declare bad int;
begin
 select count(*) into bad from public.shows_app_research_calendar_controls where control_id in ('R2026-016-MIAMI-CARNIVAL','R2026-028-WELLINGTON-NNO','R2026-046-PALM-BAY-FALL-FEST','R2026-029-RPB-ROCK-N-FALL','R2026-036-PALM-BAY-SENIOR','R2026-037-WEST-BOYNTON-SENIOR','R2026-038-FLIBS','R2026-048-VERO-HALLOWEEN','R2026-047-COCOA-FALL') and (research_status<>'CURRENT_REVERIFIED' or date_confidence<>'CURRENT_VERIFIED' or detail_data->>'current_source_checked_at'<>'2026-09-30');
 if bad<>0 then raise exception 'October closeout failed for % rows',bad; end if;
 if (select price_text from public.shows_app_research_calendar_controls where control_id='R2026-016-MIAMI-CARNIVAL') is not null then raise exception 'Miami stale price not cleared'; end if;
 if (select price_text from public.shows_app_research_calendar_controls where control_id='R2026-038-FLIBS') is not null then raise exception 'FLIBS stale price not cleared'; end if;
end $$;